// Any state change other than a scheduled retry clears the retry schedule.
func (q *Queries) SetInboxItemState(ctx context.Context, arg SetInboxItemStateParams) (InboxItem, error) {
	row := q.db.QueryRow(ctx, setInboxItemState, arg.State, arg.ID)
	var i InboxItem
	err := row.Scan(
		&i.ID,
		&i.Content,
		&i.Source,
		&i.SourceMetadata,
		&i.MediaReferences,
		&i.State,
		&i.ProcessingMetadata,
		&i.ResolvedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SourceDedupeKey,
		&i.CorrelationID,
		&i.NextRetryAt,
		&i.RetryReason,
	)
	return i, err
}

const updateProcessingAttempt = `-- name: UpdateProcessingAttempt :one
UPDATE inbox_processing_attempts SET status=$1, actions=$2, error_summary=$3, next_retry_at=$4,
  started_at=CASE WHEN $1='processing' THEN now() ELSE started_at END,
  completed_at=CASE WHEN $1 IN ('human_review','processed','failed','retryable') THEN now() ELSE completed_at END,
  updated_at=now()
WHERE id=$5 RETURNING id, inbox_item_id, idempotency_key, status, agent_name, model_profile, actions, error_summary, started_at, completed_at, created_at, updated_at, next_retry_at, runtime_state, runtime_owner, runtime_session_id, runtime_heartbeat_at
`

type UpdateProcessingAttemptParams struct {
	Status       string
	Actions      []byte
	ErrorSummary *string
	NextRetryAt  pgtype.Timestamptz
	ID           pgtype.UUID
}

func (q *Queries) UpdateProcessingAttempt(ctx context.Context, arg UpdateProcessingAttemptParams) (InboxProcessingAttempt, error) {
	row := q.db.QueryRow(ctx, updateProcessingAttempt,
		arg.Status,
		arg.Actions,
		arg.ErrorSummary,
		arg.NextRetryAt,
		arg.ID,
	)
	var i InboxProcessingAttempt
	err := row.Scan(
		&i.ID,
		&i.InboxItemID,
		&i.IdempotencyKey,
		&i.Status,
		&i.AgentName,
		&i.ModelProfile,
		&i.Actions,
		&i.ErrorSummary,
		&i.StartedAt,
		&i.CompletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.NextRetryAt,
		&i.RuntimeState,
		&i.RuntimeOwner,
		&i.RuntimeSessionID,
		&i.RuntimeHeartbeatAt,
	)
	return i, err
}
